// Command tcbench measures the typed-writes type-check (PLAN.md §3.3) on a
// site generated by gensite.
//
//	tcbench -dir sites/s50 -mode pkgs-all|pkgs-one|custom-all|custom-one|custom-hot [-n 5] [-rewrite]
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync"
	"time"

	"golang.org/x/tools/go/packages"

	"spike/typecheck/typed"
)

const mod = "example.com/site"

var (
	dir     = flag.String("dir", "sites/s50", "site directory")
	mode    = flag.String("mode", "pkgs-all", "pkgs-all | pkgs-all-deps | pkgs-one | custom-all | custom-one | custom-hot")
	one     = flag.String("pkg", "components/c017", "comma-separated packages (under orbit_gen/impl/) for the *-one modes")
	n       = flag.Int("n", 5, "iterations")
	par     = flag.Int("par", runtime.GOMAXPROCS(0), "parallel type-check workers (custom modes)")
	rewrite = flag.Bool("rewrite", false, "after the last iteration, rewrite Expr calls to typed writes in place")
	quiet   = flag.Bool("q", false, "only print the summary line")
)

func main() {
	flag.Parse()
	abs, err := filepath.Abs(*dir)
	if err != nil {
		log.Fatal(err)
	}
	*dir = abs
	var times []time.Duration
	var last *result
	for i := 0; i < *n; i++ {
		start := time.Now()
		var r *result
		switch *mode {
		case "pkgs-all":
			r = loadPackages([]string{"./orbit_gen/impl/..."}, false)
		case "pkgs-all-deps":
			r = loadPackages([]string{"./orbit_gen/impl/..."}, true)
		case "pkgs-one":
			var pats []string
			for _, p := range strings.Split(*one, ",") {
				pats = append(pats, mod+"/orbit_gen/impl/"+p)
			}
			r = loadPackages(pats, false)
		case "custom-all":
			r = custom(implDirs(), nil)
		case "custom-srcdecl":
			r = customSrcDecl()
		case "custom-one":
			r = custom(oneDirs(), nil)
		case "custom-hot":
			// Long-lived dev process: deps were imported once (not timed);
			// each iteration re-parses and re-checks one package.
			if hot == nil {
				hot = newHotImporter(oneDirs())
				start = time.Now()
			}
			r = custom(oneDirs(), hot)
		default:
			log.Fatalf("unknown mode %q", *mode)
		}
		d := time.Since(start)
		times = append(times, d)
		if !*quiet {
			fmt.Printf("  iter %d: %v  %s\n", i, d.Round(10*time.Microsecond), r.phases)
		}
		last = r
	}
	slices.Sort(times)
	fmt.Printf("%s %s: pkgs=%d exprs=%d min=%v median=%v max=%v (GOMAXPROCS=%d)\n",
		filepath.Base(*dir), *mode, last.npkgs, last.nexpr, times[0].Round(10*time.Microsecond),
		times[len(times)/2].Round(10*time.Microsecond), times[len(times)-1].Round(10*time.Microsecond), runtime.GOMAXPROCS(0))
	if *rewrite {
		stats := typed.Stats{}
		nfiles := 0
		for _, p := range last.pkgs {
			env := typed.NewEnv(typed.FindOrbit(p.types))
			src := map[string][]byte{}
			for _, f := range p.files {
				name := p.fset.File(f.Pos()).Name()
				b, err := os.ReadFile(name)
				if err != nil {
					log.Fatal(err)
				}
				src[name] = b
			}
			for name, b := range typed.Rewrite(p.fset, p.files, p.info, env, src, stats) {
				if err := os.WriteFile(name, b, 0o644); err != nil {
					log.Fatal(err)
				}
				nfiles++
			}
		}
		fmt.Printf("rewrote %d files: %v\n", nfiles, stats)
	}
}

type checked struct {
	fset  *token.FileSet
	files []*ast.File
	info  *types.Info
	types *types.Package
}

type result struct {
	npkgs, nexpr int
	phases       string
	pkgs         []checked
}

func countExpr(files []*ast.File) int {
	c := 0
	for _, f := range files {
		ast.Inspect(f, func(n ast.Node) bool {
			if call, ok := n.(*ast.CallExpr); ok {
				if sel, ok := call.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Expr" {
					c++
				}
			}
			return true
		})
	}
	return c
}

func loadPackages(patterns []string, deps bool) *result {
	mode := packages.NeedName | packages.NeedCompiledGoFiles | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax
	if deps {
		mode |= packages.NeedImports | packages.NeedDeps
	}
	cfg := &packages.Config{Mode: mode, Dir: *dir}
	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		log.Fatal(err)
	}
	r := &result{}
	for _, p := range pkgs {
		if len(p.Errors) > 0 {
			log.Fatalf("%s: %v", p.PkgPath, p.Errors)
		}
		r.npkgs++
		r.nexpr += countExpr(p.Syntax)
		r.pkgs = append(r.pkgs, checked{p.Fset, p.Syntax, p.TypesInfo, p.Types})
	}
	return r
}

func oneDirs() []string {
	var dirs []string
	for _, p := range strings.Split(*one, ",") {
		dirs = append(dirs, filepath.Join(*dir, "orbit_gen/impl", p))
	}
	return dirs
}

func implDirs() []string {
	var dirs []string
	filepath.WalkDir(filepath.Join(*dir, "orbit_gen/impl"), func(p string, d os.DirEntry, err error) error {
		if err == nil && !d.IsDir() && strings.HasSuffix(p, ".go") {
			if dd := filepath.Dir(p); len(dirs) == 0 || dirs[len(dirs)-1] != dd {
				dirs = append(dirs, dd)
			}
		}
		return nil
	})
	return dirs
}

// goListExport runs one `go list -export` for the given import paths and
// returns path → export data file. The go command builds (or finds in
// GOCACHE) export data for them and all their dependencies.
func goListExport(paths []string) map[string]string {
	args := append([]string{"list", "-e", "-export", "-f", "{{.ImportPath}}\t{{.Export}}\t{{with .Error}}{{.Err}}{{end}}"}, paths...)
	cmd := exec.Command("go", args...)
	cmd.Dir = *dir
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		log.Fatalf("go list: %v\n%s", err, stderr.String())
	}
	m := map[string]string{}
	for _, line := range strings.Split(strings.TrimRight(string(out), "\n"), "\n") {
		f := strings.Split(line, "\t")
		if len(f) != 3 {
			log.Fatalf("go list: bad line %q", line)
		}
		if f[2] != "" {
			log.Fatalf("go list %s: %s", f[0], f[2])
		}
		m[f[0]] = f[1]
	}
	return m
}

type parsed struct {
	path  string
	files []*ast.File
}

// parseDirs parses every .go file of each impl package dir, in parallel.
func parseDirs(fset *token.FileSet, dirs []string) []parsed {
	out := make([]parsed, len(dirs))
	var wg sync.WaitGroup
	sem := make(chan struct{}, *par)
	for i, d := range dirs {
		wg.Go(func() {
			sem <- struct{}{}
			defer func() { <-sem }()
			ents, _ := os.ReadDir(d)
			rel, _ := filepath.Rel(*dir, d)
			out[i].path = mod + "/" + filepath.ToSlash(rel)
			for _, e := range ents {
				if !strings.HasSuffix(e.Name(), ".go") {
					continue
				}
				f, err := parser.ParseFile(fset, filepath.Join(d, e.Name()), nil, parser.SkipObjectResolution)
				if err != nil {
					log.Fatal(err)
				}
				out[i].files = append(out[i].files, f)
			}
		})
	}
	wg.Wait()
	return out
}

// directImports is the set of non-impl imports of the parsed packages. The
// real generator knows this set without parsing (it wrote the imports).
func directImports(ps []parsed) []string {
	set := map[string]bool{}
	for _, p := range ps {
		for _, f := range p.files {
			for _, im := range f.Imports {
				path := strings.Trim(im.Path.Value, `"`)
				set[path] = true
			}
		}
	}
	var out []string
	for p := range set {
		out = append(out, p)
	}
	slices.Sort(out)
	return out
}

// lockedImporter is a gc export-data importer shared by all workers.
type lockedImporter struct {
	mu  sync.Mutex
	imp types.ImporterFrom
}

func (l *lockedImporter) Import(path string) (*types.Package, error) {
	return l.ImportFrom(path, "", 0)
}

func (l *lockedImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.imp.ImportFrom(path, dir, mode)
}

func newImporter(fset *token.FileSet, exports map[string]string) *lockedImporter {
	lookup := func(path string) (io.ReadCloser, error) {
		f, ok := exports[path]
		if !ok || f == "" {
			return nil, fmt.Errorf("no export data for %q", path)
		}
		return os.Open(f)
	}
	return &lockedImporter{imp: importer.ForCompiler(fset, "gc", lookup).(types.ImporterFrom)}
}

type hotState struct {
	fset *token.FileSet
	imp  *lockedImporter
}

var hot *hotState

func newHotImporter(dirs []string) *hotState {
	fset := token.NewFileSet()
	ps := parseDirs(fset, dirs)
	h := &hotState{fset: fset, imp: newImporter(fset, goListExport(directImports(ps)))}
	custom(dirs, h) // populate the importer's package cache
	return h
}

// custom: go list -export for the direct deps only (not the impl packages
// themselves), then parse and type-check the impl packages from source.
func custom(dirs []string, h *hotState) *result {
	t0 := time.Now()
	var fset *token.FileSet
	var imp *lockedImporter
	if h != nil {
		fset = h.fset
	} else {
		fset = token.NewFileSet()
	}
	ps := parseDirs(fset, dirs)
	t1 := time.Now()
	if h != nil {
		imp = h.imp
	} else {
		imp = newImporter(fset, goListExport(directImports(ps)))
	}
	t2 := time.Now()
	r := &result{npkgs: len(ps), pkgs: make([]checked, len(ps))}
	var wg sync.WaitGroup
	sem := make(chan struct{}, *par)
	var mu sync.Mutex
	for i, p := range ps {
		wg.Go(func() {
			sem <- struct{}{}
			defer func() { <-sem }()
			info := &types.Info{Types: map[ast.Expr]types.TypeAndValue{}}
			conf := types.Config{Importer: imp, Error: func(err error) {}}
			tp, err := conf.Check(p.path, fset, p.files, info)
			if err != nil {
				log.Fatalf("%s: %v", p.path, err)
			}
			r.pkgs[i] = checked{fset, p.files, info, tp}
			mu.Lock()
			r.nexpr += countExpr(p.files)
			mu.Unlock()
		})
	}
	wg.Wait()
	t3 := time.Now()
	r.phases = fmt.Sprintf("parse=%v golist+importer=%v check=%v", t1.Sub(t0).Round(10*time.Microsecond), t2.Sub(t1).Round(10*time.Microsecond), t3.Sub(t2).Round(10*time.Microsecond))
	return r
}

// srcImporter type-checks orbit_gen/decl packages from source on first use
// (memoized, safe for concurrent use) and imports everything else from
// export data. Only non-generated packages (user code, runtime, std) need
// go list -export, so a user-package edit compiles just that package before
// the check, and decl packages never need compiling for the check.
type srcImporter struct {
	fset  *token.FileSet
	exp   *lockedImporter
	decls map[string][]*ast.File
	mu    sync.Mutex
	done  map[string]*declResult
}

type declResult struct {
	once sync.Once
	pkg  *types.Package
	err  error
}

func (s *srcImporter) Import(path string) (*types.Package, error) { return s.ImportFrom(path, "", 0) }

func (s *srcImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	files, ok := s.decls[path]
	if !ok {
		return s.exp.ImportFrom(path, dir, mode)
	}
	s.mu.Lock()
	d := s.done[path]
	if d == nil {
		d = &declResult{}
		s.done[path] = d
	}
	s.mu.Unlock()
	d.once.Do(func() {
		conf := types.Config{Importer: s}
		d.pkg, d.err = conf.Check(path, s.fset, files, nil)
	})
	return d.pkg, d.err
}

func customSrcDecl() *result {
	t0 := time.Now()
	fset := token.NewFileSet()
	impls := parseDirs(fset, implDirs())
	var declDirs []string
	for _, p := range impls {
		declDirs = append(declDirs, filepath.Join(*dir, "orbit_gen/decl", strings.TrimPrefix(p.path, mod+"/orbit_gen/impl/")))
	}
	decls := parseDirs(fset, declDirs)
	t1 := time.Now()
	var ext []string
	for _, p := range directImports(append(append([]parsed{}, impls...), decls...)) {
		if !strings.HasPrefix(p, mod+"/orbit_gen/") {
			ext = append(ext, p)
		}
	}
	si := &srcImporter{fset: fset, exp: newImporter(fset, goListExport(ext)), decls: map[string][]*ast.File{}, done: map[string]*declResult{}}
	for _, d := range decls {
		si.decls[d.path] = d.files
	}
	t2 := time.Now()
	r := &result{npkgs: len(impls), pkgs: make([]checked, len(impls))}
	var wg sync.WaitGroup
	sem := make(chan struct{}, *par)
	var mu sync.Mutex
	for i, p := range impls {
		wg.Go(func() {
			sem <- struct{}{}
			defer func() { <-sem }()
			info := &types.Info{Types: map[ast.Expr]types.TypeAndValue{}}
			conf := types.Config{Importer: si}
			tp, err := conf.Check(p.path, fset, p.files, info)
			if err != nil {
				log.Fatalf("%s: %v", p.path, err)
			}
			r.pkgs[i] = checked{fset, p.files, info, tp}
			mu.Lock()
			r.nexpr += countExpr(p.files)
			mu.Unlock()
		})
	}
	wg.Wait()
	t3 := time.Now()
	r.phases = fmt.Sprintf("parse=%v golist(user+std)+importer=%v check(decl+impl)=%v", t1.Sub(t0).Round(10*time.Microsecond), t2.Sub(t1).Round(10*time.Microsecond), t3.Sub(t2).Round(10*time.Microsecond))
	return r
}
